package com.loanms.service;
import com.loanms.db.Database; import java.sql.*; import java.util.*;
public class ReportService {
 public Map<String,Double> summary(){Map<String,Double> m=new LinkedHashMap<>();String[] q={"SELECT COUNT(*) FROM customer","SELECT COUNT(*) FROM loan","SELECT COALESCE(SUM(principal),0) FROM loan","SELECT COALESCE(SUM(amount),0) FROM payment","SELECT COALESCE(SUM(principal),0) FROM loan WHERE status='Pending'","SELECT COALESCE(SUM(principal),0) FROM loan WHERE status='Active'","SELECT COALESCE(SUM(principal),0) FROM loan WHERE status='Completed'"};String[] k={"Customers","Loans","Loan Amount","Collected","Pending Amount","Active Amount","Completed Amount"};try(Connection c=Database.connect()){for(int i=0;i<q.length;i++)try(Statement s=c.createStatement();ResultSet r=s.executeQuery(q[i])){m.put(k[i],r.next()?r.getDouble(1):0);}return m;}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<String> paymentHistory(int loanId){List<String> out=new ArrayList<>();String q="SELECT id,amount,paid_at FROM payment WHERE loan_id=? ORDER BY paid_at DESC";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,loanId);try(ResultSet r=p.executeQuery()){while(r.next())out.add("Payment #"+r.getInt(1)+" | "+String.format("%.2f",r.getDouble(2))+" | "+r.getString(3));}return out;}catch(SQLException e){throw new IllegalStateException(e);}}
}
